#include <sstream>
#include <vector>
#include <iostream>
using namespace std;

vector<int> parseInts(string str) {
    stringstream ss(str);
    vector<int> result;  // to store integers
    int num;
    char ch;

    while (ss >> num) {
        result.push_back(num);
        ss >> ch;  // discard comma
    }

    return result;
}

int main() {
    string str;
    getline(cin, str);  // read full line with commas

    vector<int> integers = parseInts(str);
    for (int i = 0; i < integers.size(); i++) {
        cout << integers[i] << "\n";
    }

    return 0;
}
